#' Demultiplex FASTQ reads using primer and tag information
#'
#' \code{demultiplex()} assigns each FASTQ read to a reaction based on matching forward
#' and reverse primers, as well as optional tag sequences. For each read, the
#' identified experiment, reaction ID, reaction tag, and primer mismatches are recorded in a
#' `"demultiplex"` JSON block appended to the FASTA header.
#'
#' Reaction tags are short oligonucleotide labels attached to primers before
#' PCR products are pooled for library preparation (tag-based multiplexing).
#' The supplied reaction table uses paired 8-bp tags. Tag length is determined
#' by the table; the function does not require 8-bp tags. Tags identify PCR
#' reactions, not different target-gene markers or sequencing-library indices.
#'
#' @param fastq_file (character) path to the input FASTQ file. The file may be
#'   plain text or gzip-compressed (suffix \code{.gz}).
#'
#' @param reaction_table (character) path to a CSV/TSV file containing primer and
#'   tag definitions. The columns are \code{experiment},
#'   \code{reaction_id}, \code{reaction_tag}, \code{forward_primer}, and
#'   \code{reverse_primer}. A paired tag is written as
#'   \code{forward_tag:reverse_tag}; a single tag is used for both directions.
#'
#' @param identified_output (character) path to the output file that receives
#'   reads successfully assigned to a reaction. If \code{compress_output = TRUE}
#'   or the file name ends with \code{.gz}, the file is gzip-compressed.
#'
#' @param unidentified_output (character) path to the output file for reads
#'   that cannot be matched to any reaction based on the specified primers and
#'   tags. Compression behavior is identical to \code{identified_output}.
#'
#' @param n_threads (integer) number of parallel threads used for matching
#'   primers and tags. When OpenMP support is available, multiple threads
#'   accelerate demultiplexing.
#'
#' @param with_tag (logical) if \code{TRUE}, tag sequences must be present
#'   and matched in addition to primers. If \code{FALSE}, only primer matching
#'   is performed.
#'
#' @param compress_output (logical) if \code{TRUE}, write all output files in
#'   gzip format regardless of output file name suffix.
#'
#' @param compress_level (integer, between 0 and 9) gzip compression level
#'   applied when writing compressed output.
#'
#' @param primer_mismatch (integer) maximum number of mismatches allowed when
#'   matching primers. Tag matching does not allow mismatches.
#'
#' @return
#' Invisibly returns \code{NULL}. Identified reads are written to
#' \code{identified_output}, whereas unmatched reads are written to
#' \code{unidentified_output}. Each identified read receives a `"demultiplex"`
#' JSON block in the header containing experiment, sample, tag, primer matches,
#' and mismatch counts.
#' @export
demultiplex <- function(fastq_file, reaction_table, identified_output, unidentified_output, n_threads = 4L, with_tag = TRUE, compress_output = FALSE, compress_level = 6L, primer_mismatch = 3L) {
    invisible(.Call(`_METAeDNA_demultiplex`, fastq_file, reaction_table, identified_output, unidentified_output, n_threads, with_tag, compress_output, compress_level, primer_mismatch))
}

#' Split tagged paired-end reads by PCR reaction
#'
#' Read paired FASTQ files in batches, assign each pair by its forward and
#' reverse tags, remove the matched tags and primers, and write one FASTQ pair
#' per reaction. This function only splits reads; it does not run DADA2.
#' Reaction tags are oligonucleotide labels used for tag-based multiplexing
#' before library pooling. The example tags are 8 bp long; other lengths are
#' accepted as specified in `reaction_table`.
#'
#' @param fastq_1 Path to the R1 FASTQ file.
#' @param fastq_2 Path to the R2 FASTQ file.
#' @param reaction_table CSV or tab-delimited reaction table containing
#'   `experiment`, `reaction_id`, `reaction_tag`, `forward_primer`, and
#'   `reverse_primer`. Write paired tags as `forward_tag:reverse_tag`.
#' @param output_dir Empty directory in which the split FASTQ files are written.
#' @param n_threads Number of threads used to match and trim each batch.
#' @param batch_size Number of paired reads processed in each batch.
#' @param compress_output Write gzip-compressed FASTQ files.
#' @param compress_level Gzip compression level from 0 to 9.
#' @param with_primer Remove the primers following the tags.
#'
#' @return `NULL`, invisibly. Split FASTQ files are written to `output_dir`.
#'
#' @details Tags are matched exactly. Primers may contain IUPAC bases but are
#'   matched without mismatches. A read pair is assigned only when R1 and R2
#'   match the same row in `reaction_table`.
#'
#' @examples
#' \dontrun{
#' barcode_split(
#'   fastq_1 = "run_R1.fastq.gz",
#'   fastq_2 = "run_R2.fastq.gz",
#'   reaction_table = "reactions.csv",
#'   output_dir = "split_fastq",
#'   n_threads = 8
#' )
#' }
#' @export
barcode_split <- function(fastq_1, fastq_2, reaction_table, output_dir, n_threads = 4L, batch_size = 100000L, compress_output = TRUE, compress_level = 6L, with_primer = TRUE) {
    invisible(.Call(`_METAeDNA_barcode_split`, fastq_1, fastq_2, reaction_table, output_dir, n_threads, batch_size, compress_output, compress_level, with_primer))
}

#' Denoise FASTA sequences using abundance and local sequence similarity
#'
#'
#' For each sequence, a `"denoise"` JSON block is appended to the header
#' summarizing per-PCR status and counts, and the overall
#' \code{size=} and \code{"total_count"} fields are updated to match the
#' retained counts. Output can be written either uncompressed or gzip-compressed.
#'
#' @param fasta_file (character) string; path to the input FASTA file. The file
#'   may be plain text or gzip-compressed (suffix \code{.gz}).
#' @param output_fasta (character )string; path to the output FASTA file. If the
#'   file name ends with \code{.gz} or \code{compress_output = TRUE}, the
#'   output is gzip-compressed.
#' @param sequence_min_L (integer); minimum sequence length to retain. Sequences
#'   shorter than this threshold are discarded before denoising.
#' @param sequence_max_L (integer); maximum sequence length to retain. Sequences
#'   longer than this threshold are discarded before denoising.
#' @param min_count (integer) minimum total read count (summed over all PCRs)
#'   required to keep a sequence. Sequences with total counts below this
#'   threshold are removed before graph construction.
#' @param threshold (double) scalar in (0,1); abundance ratio threshold used
#'   to direct edges in the neighbor graph. For a pair of neighboring
#'   sequences with counts \code{high} and \code{low}, an edge
#'   \code{high -> low} is created only if \code{low/high < threshold}. These
#'   directed edges are then used to classify \code{"head"}, \code{"internal"},
#'   and \code{"singleton"} sequences per PCR.
#' @param n_threads (integer) number of parallel threads used for neighbor
#'   search and labeling. When OpenMP is available, values greater than 1
#'   enable multi-threaded computation; otherwise this argument is ignored.
#' @param max_diff  (integer >= 0) maximum number of substitutions allowed
#'   between two sequences for them to be considered neighbors. Setting
#'   \code{max_diff = 1} restricts neighbors to Hamming distance 1 (plus any
#'   allowed indels via \code{max_indel}).
#' @param max_indel (integer >= 0) maximum absolute indel size (in base pairs)
#'   allowed between two sequences for them to be considered neighbors.
#'   \code{max_indel = 0} restricts neighbors to equal length; \code{max_indel = 1}
#'   additionally allows single-base insertions/deletions.
#' @param keep_internal (logical) if \code{FALSE}, sequences that are labeled
#'   \code{"internal"} in all PCRs are removed from the output. For sequences
#'   that are kept, any per-PCR entries with status \code{"internal"} may be
#'   dropped from the per-PCR statistics.
#' @param keep_previous_stat (logical) if \code{TRUE}, the existing JSON block
#'   in the header (typically produced by previous steps such as \code{unique})
#'   is preserved and the new `"denoise"` block is appended to it. If
#'   \code{FALSE}, the old statistics block is discarded and the header is
#'   rebuilt to contain only the sequence identifier and the new `"denoise"`
#'   block (with updated \code{size=} and \code{"total_count"} fields).
#' @param compress_output (logical) if \code{TRUE}, the output FASTA is written
#'   as gzip regardless of the file name suffix.
#' @param enable_avx2 (logical) use AVX2 instructions for sequence comparisons
#'   when supported by the current CPU.
#' @param debug (logical) print additional diagnostic output.
#' @param compress_level (integer,between 0 and 9) gzip compression level passed
#'   to \code{gzopen()} when \code{compress_output} is enabled or the output
#'   file name ends with \code{.gz}. Higher values give better compression at
#'   the cost of slower writing.
#'
#' @return
#' Invisibly returns \code{NULL}. The main result is the FASTA file written to
#' \code{output_fasta}, where each header line has been updated to include a
#' `"denoise"` JSON block with per-PCR counts and status labels, together with
#' summary tallies of \code{"head"}, \code{"internal"}, and \code{"singleton"}
#' occurrences across all PCRs.
#' @details
#' For each PCR independently, sequences are first filtered by length and total
#' abundance thresholds. A local neighbor graph is then constructed by
#' connecting sequences that differ by at most a user-defined number of
#' substitutions (\code{max_diff}) and/or short indels (\code{max_indel}). Edges
#' are directed from higher-abundance sequences to lower-abundance sequences
#' when their abundance ratio satisfies the specified \code{threshold}. This
#' directed graph is used to classify sequences into three categories per PCR:
#' \code{"head"} (no outgoing edges), \code{"internal"} (receiving edges from
#' higher-abundance neighbors), and \code{"singleton"} (no neighbors). This algorithm was described by Boyer et. al.,(2016)
#'
#' @section Citations: Boyer, F., Mercier, C., Bonin, A., Le Bras, Y., Taberlet, P. and Coissac, E. (2016), obitools: a unix-inspired software package for DNA metabarcoding. Mol Ecol Resour, 16: 176-182. \url{https://doi.org/10.1111/1755-0998.12428}
#' @export
denoise <- function(fasta_file, output_fasta, sequence_min_L = 1L, sequence_max_L = 1000L, min_count = 1L, threshold = 0.05, n_threads = 32L, max_diff = 1L, max_indel = 0L, keep_internal = TRUE, keep_previous_stat = FALSE, compress_output = FALSE, enable_avx2 = TRUE, debug = FALSE, compress_level = 6L) {
    invisible(.Call(`_METAeDNA_denoise`, fasta_file, output_fasta, sequence_min_L, sequence_max_L, min_count, threshold, n_threads, max_diff, max_indel, keep_internal, keep_previous_stat, compress_output, enable_avx2, debug, compress_level))
}

#' Validate paired FASTQ files
#'
#' Read R1 and R2 together and check that every FASTQ record has a corresponding
#' mate before read merging or paired demultiplexing.
#'
#' @param forward Character string giving the path to the R1 FASTQ file. Plain
#'   text and gzip-compressed files are supported.
#' @param reverse Character string giving the path to the R2 FASTQ file. Plain
#'   text and gzip-compressed files are supported.
#' @param n_threads Number of threads. Defaults to 4, as in `pairend()`.
#' @param batch_size Number of read pairs per batch. Defaults to 1000000,
#'   as in `pairend()`.
#'
#' @details
#' Both files are read from beginning to end. For every pair, the function
#' checks the FASTQ structure, sequence and quality lengths, Phred+33 quality
#' range, and read identifier. Only the first field of each identifier is
#' compared; text following a space or tab is ignored. Conventional `/1` and
#' `/2` mate suffixes are also ignored. For example, `@read42/1` and
#' `@read42/2` are treated as the same read identifier.
#'
#' An error is raised when the files are identical, cannot be opened, contain
#' invalid FASTQ records, contain different numbers of records, or have mates
#' in different orders. Empty input files are not accepted. The function only
#' validates the files and does not modify or create sequence data.
#' Files are read in batches using the shared FASTQ reader. With multiple
#' threads, the two files are read concurrently and identifiers are checked
#' in parallel. Without OpenMP, processing is sequential.
#'
#' @return A numeric value giving the number of validated read pairs.
#'
#' @examples
#' forward <- system.file("extdata", "trnL_40k_1.fq.gz", package = "METAeDNA")
#' reverse <- system.file("extdata", "trnL_40k_2.fq.gz", package = "METAeDNA")
#' validate_paired_fastq(forward, reverse)
#'
#' @export
validate_paired_fastq <- function(forward, reverse, n_threads = 4L, batch_size = 1000000L) {
    .Call(`_METAeDNA_validate_paired_fastq`, forward, reverse, n_threads, batch_size)
}

#' Summarize FASTQ quality and base composition
#'
#' Inspect reads from the beginning of a FASTQ file and summarize sequencing
#' quality and nucleotide composition at each read position. The result can be
#' used to examine quality loss toward the read end, positional nucleotide
#' bias, and the number of reads that reach each position.
#'
#' @param path Character string giving the path to a plain or gzip-compressed
#'   FASTQ file. Quality scores must use Phred+33 encoding.
#' @param max_records Non-negative integer giving the maximum number of records
#'   read from the beginning of the file. The default is 100000. Use 0 to scan
#'   the complete file. This is a prefix preview rather than a random sample.
#' @param n_threads Number of threads used for statistics. Defaults to 4.
#' @param batch_size Number of reads per batch. Defaults to 1000000.
#' @param debug Print processing stages to help locate slow operations.
#'
#' @details
#' The shared FASTQ reader reads one batch at a time; quality and nucleotide
#' counts are computed in parallel. Only the current batch is retained.
#' Without OpenMP, statistics are computed sequentially.
#' A, C, G, and T are reported
#' separately. N and any other ambiguity codes are combined as `N_other`.
#'
#' If the identifiers contain the `pairend` metadata written by `pairend()`,
#' the function also summarizes overlap lengths and mismatch counts. These
#' fields describe only the merged reads present in the inspected file. The
#' resulting `mismatch_rate` is not an error rate measured against a reference
#' sequence.
#'
#' @return A list with two data frames:
#' \describe{
#'   \item{`positions`}{One row per read position, containing:
#'     \itemize{
#'       \item `position`: base position counted from the beginning of the
#'         stored read, starting at 1. Reads are not realigned or reoriented.
#'       \item `reads`: number of inspected reads containing a base at this
#'         position. Shorter reads do not contribute to later positions.
#'       \item `mean_quality`: arithmetic mean of the Phred scores at this
#'         position, after subtracting the Phred+33 encoding offset. This is
#'         a quality score, not a mean error probability.
#'       \item `q10`: 10th percentile of the Phred scores at this position.
#'       \item `q25` and `q75`: 25th and 75th percentiles, used as the lower
#'         and upper edges of quality boxes.
#'       \item `median`: 50th percentile of the Phred scores at this position.
#'       \item `q90`: 90th percentile of the Phred scores at this position.
#'         Each percentile is the smallest observed score whose cumulative
#'         count reaches the requested fraction; no interpolation is used.
#'       \item `A`: fraction of bases called A at this position.
#'       \item `C`: fraction of bases called C at this position.
#'       \item `G`: fraction of bases called G at this position.
#'       \item `T`: fraction of bases called T at this position.
#'       \item `N_other`: fraction of N bases and all other ambiguity codes
#'         at this position. Base counting is case-insensitive. All five
#'         fractions use `reads` as the denominator, range from 0 to 1,
#'         and sum to 1 at each position; they are not percentages.
#'     }}
#'   \item{`summary`}{One row containing:
#'     \itemize{
#'       \item `filename`: input filename without its directory.
#'       \item `file_type`: conventional nucleotide base calls in FASTQ format.
#'       \item `encoding`: required Sanger / Illumina 1.8+ (Phred+33) encoding;
#'         this is the assumed encoding, not automatic encoding detection.
#'       \item `total_megabases`: inspected bases divided by 1000000.
#'       \item `min_length`, `max_length`, `mean_length`, and `median_length`:
#'         shortest, longest, mean, and median inspected read lengths in bases.
#'       \item `gc_percent`: 100 times the number of G and C calls divided by
#'         all inspected bases, including ambiguous bases.
#'       \item `reads` and `bases`: inspected read and base counts;
#'       \item `q20_fraction` and `q30_fraction`: fractions of bases with
#'         Phred scores of at least 20 and 30;
#'       \item `annotated_reads`: reads containing valid `pairend` metadata;
#'       \item `overlap_bases` and `overlap_mismatches`: corresponding totals;
#'       \item `mismatch_rate`: `overlap_mismatches / overlap_bases`, or `NA`
#'         when overlap metadata is unavailable.
#'     }}
#' }
#' All summary counts and length statistics describe only the inspected
#' records. Use `max_records = 0` to summarize the whole file. Empty files
#' have zero counts and missing length and GC statistics.
#'
#' @examples
#' fastq <- system.file("extdata", "trnL_40k_1.fq.gz", package = "METAeDNA")
#' result <- fastq_profile(fastq, max_records = 1000)
#' head(result$positions)
#' result$summary
#' # Boxes: 25th--75th percentiles; whiskers: 10th--90th percentiles.
#' ggplot2::ggplot(result$positions, ggplot2::aes(position, mean_quality)) +
#'   ggplot2::geom_boxplot(ggplot2::aes(group = position, ymin = q10,
#'     lower = q25, middle = median, upper = q75, ymax = q90),
#'     stat = "identity", width = 0.7, fill = "#A6CEE3") +
#'   ggplot2::geom_line(colour = "#3B4992") +
#'   ggplot2::labs(x = "Base position", y = "Phred quality") +
#'   ggplot2::theme_classic(base_size = 10)
#'
#' \donttest{
#' merged <- tempfile(fileext = ".fastq.gz")
#' reverse <- system.file("extdata", "trnL_40k_2.fq.gz", package = "METAeDNA")
#' pairend(fastq, reverse, merged, n_threads = 1)
#' fastq_profile(merged, max_records = 1000)$summary
#' }
#'
#' @export
fastq_profile <- function(path, max_records = 100000L, n_threads = 4L, batch_size = 1000000L, debug = FALSE) {
    .Call(`_METAeDNA_fastq_profile`, path, max_records, n_threads, batch_size, debug)
}

#' Merge paired-end reads from FASTQ files
#'
#' \code{pairend()} merges paired-end reads from two FASTQ files by identifying
#' overlapping regions between read 1 and the reverse-complement of read 2.
#' Overlap length, mismatch allowance, and overlap scoring can be customized.
#'
#' @param fastq_1 (character) path to the FASTQ file containing read 1.
#'   The file may be plain text or gzip-compressed.
#' @param fastq_2 (character) path to the FASTQ file containing read 2.
#'   The file may be plain text or gzip-compressed.
#' @param out_file (character) path to the output FASTQ file containing merged
#'   paired-end reads. If \code{compress_output = TRUE} or the file name ends
#'   with \code{.gz}, the output is gzip-compressed.
#'
#' @param compress_level (integer, 0–9) gzip compression level passed to
#'   \code{gzopen()} when writing compressed output.
#'
#' @param min_overlap (integer) minimum overlap length required for merging
#'   two reads. Overlaps shorter than this threshold are not used.
#'
#' @param max_mismatches (integer) maximum number of mismatched bases allowed
#'   within the overlapping region between the two reads. This is an additional
#'   METAeDNA filter applied after the PEAR OES p-value test.
#'
#' @param compress_output (logical) if \code{TRUE}, write the output FASTQ file
#'   in gzip format regardless of the suffix of \code{out_file}.
#'
#'
#' @param alpha (double) weight assigned to evidence supporting a base match in
#'   overlap scoring.
#'
#' @param beta (double) weight assigned to evidence against a base match in
#'   overlap scoring.
#'
#' @param n_threads (integer) number of parallel threads used for merging.
#'   When OpenMP is available, multi-threading accelerates overlap detection
#'   and merging within each processed batch.
#'
#' @param batch_size (integer) number of read pairs processed per batch.
#'   Larger batch sizes reduce I/O overhead but increase memory usage.
#'
#' @return
#' Invisibly returns \code{NULL}. The merged reads are written to
#' \code{out_file}, with each merged record containing updated sequence,
#' quality string, and a JSON block appended to the identifier summarizing
#' overlap size, mismatch count, and overlap score.
#' @export
pairend <- function(fastq_1, fastq_2, out_file, compress_level = 6L, min_overlap = 15L, max_mismatches = 3L, compress_output = FALSE, alpha = 1.0, beta = -1.0, n_threads = 4L, batch_size = 1000000L) {
    invisible(.Call(`_METAeDNA_pairend`, fastq_1, fastq_2, out_file, compress_level, min_overlap, max_mismatches, compress_output, alpha, beta, n_threads, batch_size))
}

#' Reorder R2 FASTQ records to match R1
#'
#' Reorder the records in a paired-end R2 FASTQ file so that their identifiers
#' occur in the same order as the corresponding records in R1. Both files
#' must contain the same reads; only their order may differ.
#'
#' @param fastq_1 Character string giving the path to the R1 FASTQ file. Its
#'   record order is used as the reference. Plain and gzip-compressed files are
#'   supported.
#' @param fastq_2 Character string giving the path to the R2 FASTQ file that
#'   will be reordered. Plain and gzip-compressed files are supported.
#' @param output_fastq Character string giving the output path for the reordered
#'   R2 records. The output must not overwrite either input file.
#' @param compress_output Logical value indicating whether the output should be
#'   gzip-compressed. A file name ending in `.gz` also enables compression.
#' @param compress_level Integer from 0 to 9 giving the gzip compression level.
#'   This argument is ignored for uncompressed output.
#'
#' @details
#' Only the first field of each FASTQ identifier is compared. Text following a
#' space or tab is ignored, as are conventional `/1` and `/2` mate suffixes.
#' For example, `@read42/1 1:N:0:1` and `@read42/2 2:N:0:1` are treated as a
#' pair.
#'
#' R2 records are indexed in memory and then written in R1 order. Memory use
#' therefore increases with the size of the R2 file. Both files must contain
#' exactly the same unique identifiers. An error is raised for invalid FASTQ
#' records, duplicate or empty identifiers, missing mates, extra R2 records,
#' unreadable files, or an output path that refers to an input file.
#'
#' The sequence, quality string, and complete original R2 header are preserved;
#' only the order of the R2 records changes. R1 is never modified.
#'
#' @return Invisibly returns `NULL`. Reordered R2 records are written to
#'   `output_fastq`.
#'
#' @examples
#' \donttest{
#' r1 <- system.file("extdata", "trnL_40k_1.fq.gz", package = "METAeDNA")
#' r2 <- system.file("extdata", "trnL_40k_2.fq.gz", package = "METAeDNA")
#' output <- tempfile(fileext = ".fastq.gz")
#' reorder_fastq(r1, r2, output)
#' validate_paired_fastq(r1, output)
#' }
#'
#' @export
reorder_fastq <- function(fastq_1, fastq_2, output_fastq, compress_output = FALSE, compress_level = 6L) {
    invisible(.Call(`_METAeDNA_reorder_fastq`, fastq_1, fastq_2, output_fastq, compress_output, compress_level))
}

#' Collapse duplicate sequences in a FASTA/FASTQ file
#'
#' \code{collapse_sequences()} identifies identical sequences in an input FASTA or FASTQ
#' file and collapses them into unique sequence entries. For each unique
#' sequence, the function aggregates the total read count and the per-PCR
#' (experiment–sample) counts derived from the input header metadata. The
#' resulting dereplicated FASTA file contains one record per unique sequence,
#' with an updated `"stat"` JSON block summarizing the merged counts and the
#' sequence length. If paired-end metadata was present (in a `"pairend"`
#' block), it is preserved in the output.
#'
#' @param fasta_file (character) path to the input FASTA or FASTQ file. The
#'   file may be plain text or gzip-compressed (suffix \code{.gz}).
#'
#' @param output_fasta (character) path to the dereplicated output FASTA file.
#'   If \code{compress_output = TRUE} or if the file name ends with \code{.gz},
#'   the file is written in gzip-compressed format.
#'
#' @param n_threads (integer) number of threads used for processing. When
#'   OpenMP support is available, multiple threads accelerate sequence hashing
#'   and merging.
#'
#' @param compress_output (logical) whether to write the output file in gzip
#'   format regardless of the suffix of \code{output_fasta}.
#'
#' @param compress_level (integer, between 0 and 9) gzip compression level used
#'   when writing compressed output.
#'
#' @param batch_size (integer) number of records to read and process per batch.
#'   Larger values reduce I/O overhead but require more memory.
#'
#' @details
#' Each input record is parsed into:
#' \itemize{
#'   \item the sequence identifier (prefix before any metadata block),
#'   \item optional \code{"pairend"} metadata block,
#'   \item optional experiment and sample identifiers contained in
#'         \code{"stat"} or previous pipeline modules.
#' }
#' The function maintains per-sequence counters:
#' \itemize{
#'   \item \code{total_count}: total occurrences of the same sequence,
#'   \item per-PCR counts: \code{exp → sample → count}.
#' }
#' After all batches are processed, unique sequences are written to the output
#' FASTA file. Each header contains:
#' \itemize{
#'   \item \code{size=}: total count of the sequence,
#'   \item a `"stat"` JSON block summarizing per-PCR counts,
#'   \item preserved `"pairend"` metadata when present.
#' }
#'
#' @return
#' Invisibly returns \code{NULL}. The dereplicated sequences are written to
#' \code{output_fasta}. Each output record includes updated counts, preserved
